WITH src AS (SELECT * FROM store_sales WHERE store_id = 6 AND units > 24), summary AS (SELECT CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END AS sale_cohort, AVG(revenue) AS avg_revenue FROM src GROUP BY CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT * FROM summary WHERE avg_revenue < 1200 ORDER BY sale_cohort;
